script:
(function(){
if(!window.__lsWa){window.__lsWa=1;document.addEventListener('click',function(e){
 var a=e.target&&e.target.closest?e.target.closest('.ls a[data-cta-position]'):null;if(!a)return;
 var ev={page_path:location.pathname,source:'ls_'+a.getAttribute('data-cta-position')};
 window.dataLayer=window.dataLayer||[];window.dataLayer.push(Object.assign({event:'whatsapp_click'},ev));
 if(typeof window.gtag==='function')window.gtag('event','whatsapp_click',ev);
},true);}
function ss(k){try{return sessionStorage.getItem(k)||''}catch(e){return ''}}
function v(fd,k){return String(fd.get(k)||'').trim()}
document.querySelectorAll('.ls form.ls-lead').forEach(function(f){
 if(f.dataset.on)return;f.dataset.on=1;
 f.addEventListener('submit',function(e){
  e.preventDefault();
  var fd=new FormData(f),nome=v(fd,'nome'),tel=v(fd,'tel');
  var m=f.querySelector('.ls-msg')||f.querySelector('#f-msg');
  if(!nome||!tel){if(m)m.textContent='Preencha nome e WhatsApp para continuar.';return;}
  var btn=f.querySelector('button[type=submit]');if(btn){btn.disabled=true;}
  var tipo=v(fd,'tipo')||document.title.split('|')[0].trim();
  var extra=[v(fd,'sit')&&('Situação: '+v(fd,'sit')),v(fd,'prazo')&&('Prazo: '+v(fd,'prazo')),v(fd,'cnae')&&('CNAE/CNPJ: '+v(fd,'cnae'))].filter(Boolean).join(' · ');
  var body={Nome:nome,WhatsApp:tel,Tipo_Edificacao:tipo,Endereco_Bairro:v(fd,'end'),service:'Licença sanitária',
   Mensagem:(extra?extra+' · ':'')+'Pedido feito na página: '+document.title,
   Pagina_Entrada:ss('drd2_landing_page')||location.href,URL_Atual:location.href,Caminho:location.pathname,Titulo_Pagina:document.title,
   Referrer:ss('drd2_referrer')||document.referrer||'direto',UTM_Source:ss('drd2_utm_source'),UTM_Medium:ss('drd2_utm_medium'),
   UTM_Campaign:ss('drd2_utm_campaign'),UTM_Term:ss('drd2_utm_term'),UTM_Content:ss('drd2_utm_content'),
   Tipo_Pagina:'licenca-sanitaria',Segmento_Provavel:'licenca-sanitaria'};
  var wa='https://wa.me/5511942232969?text='+encodeURIComponent('Olá! Sou '+nome+' ('+tel+'). Acabei de pedir retorno pelo site sobre licença sanitária: '+tipo+'.');
  function done(ok){
   if(btn)btn.disabled=false;
   if(ok){
    window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:'lead_form_submit',page_path:location.pathname,source:location.pathname,intent:'licenca-sanitaria',occupation:tipo});
    if(typeof window.gtag==='function')window.gtag('event','lead_form_submit',{page_path:location.pathname,source:location.pathname,intent:'licenca-sanitaria',occupation:tipo});
    f.reset();
   }
   if(m)m.innerHTML=(ok?'Recebemos! Vamos chamar você no WhatsApp. ':'Não conseguimos enviar agora. ')+'<a href=\"'+wa+'\" target=\"_blank\" rel=\"noopener\" data-wa-tracked=\"true\">'+(ok?'Quer agilizar? Abra o WhatsApp.':'Fale com a gente pelo WhatsApp.')+'</a>';
  }
  fetch('/api/lead',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(body)})
   .then(function(r){done(r.ok)}).catch(function(){done(false)});
 });
});})();
